#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

long long minll(long long a, long long b) {
    return a < b ? a : b;
}
long long maxll(long long a, long long b) {
    return a > b ? a : b;
}
int cmpint(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
int n, g[205][205], visited[205], order[205], used, part[205], count;
void dfs1(int u) {
    visited[u] = 1;
    for (int v = 0; v < n; v++)
        if (g[u][v] && !visited[v])
            dfs1(v);
    order[used++] = u;
}
void dfs2(int u) {
    part[u] = count;
    for (int v = 0; v < n; v++)
        if (g[v][u] && !part[v])
            dfs2(v);
}
void scc(void) {
    for (int i = 0; i < n; i++)
        if (!visited[i])
            dfs1(i);
    for (int i = n - 1; i >= 0; i--)
        if (!part[order[i]]) {
            count++;
            dfs2(order[i]);
        }
}

int main(void) {
    int m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        g[u][v] = 1;
    }
    scc();
    long long sum[205] = {0}, dp[205] = {0};
    int dag[205][205] = {0}, in[205] = {0}, q[205], h = 0, t = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        sum[part[i]] += x;
    }
    for (int u = 0; u < n; u++)
        for (int v = 0; v < n; v++)
            if (g[u][v] && part[u] != part[v] && !dag[part[u]][part[v]]) {
                dag[part[u]][part[v]] = 1;
                in[part[v]]++;
            }
    for (int i = 1; i <= count; i++) {
        dp[i] = sum[i];
        if (!in[i])
            q[t++] = i;
    }
    long long ans = 0;
    while (h < t) {
        int u = q[h++];
        ans = maxll(ans, dp[u]);
        for (int v = 1; v <= count; v++)
            if (dag[u][v]) {
                dp[v] = maxll(dp[v], dp[u] + sum[v]);
                if (--in[v] == 0)
                    q[t++] = v;
            }
    }
    printf("%lld\n", ans);
    return 0;
}

