    return a > b ? a : b;
}
int cmpint(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
int n, g[205][205], tin[205], low[205], size[205], timer, root, component[205],
    nodes[205], used;
long long cut[205], bridge[205][205];
void lowdfs(int u, int parent) {
    tin[u] = low[u] = ++timer;
    size[u] = 1;
    nodes[used++] = u;
    long long sum = 0, pairs = 0;
    for (int v = 0; v < n; v++)
        if (g[u][v] && v != parent) {
            if (!tin[v]) {
                lowdfs(v, u);
                size[u] += size[v];
                if (low[v] < low[u])
                    low[u] = low[v];
                if (low[v] >= tin[u]) {
                    pairs += sum * size[v];
                    sum += size[v];
                }
                if (low[v] > tin[u])
                    bridge[u][v] = bridge[v][u] = size[v];
            } else if (tin[v] < low[u])
                low[u] = tin[v];
        }
    cut[u] = pairs;
    component[u] = (int)sum;
}
int compsize[205];

int main(void) {
    int m, eu[3005], ev[3005];
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++) {
        scanf("%d%d", &eu[i], &ev[i]);
        g[eu[i]][ev[i]] = g[ev[i]][eu[i]] = 1;
    }
    for (int s = 0; s < n; s++)
        if (!tin[s]) {
            used = 0;
            lowdfs(s, -1);
            for (int j = 0; j < used; j++) {
                int u = nodes[j];
                compsize[u] = used;
                cut[u] += 1LL * component[u] * (used - 1 - component[u]);
            }
        }
    for (int i = 0; i < n; i++)
        printf("%s%lld", i ? " " : "", cut[i]);
    puts("");
    return 0;
}

