int n, w[205][205];
const long long INF = 4000000000000000LL;

int main(void) {
    int m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++) {
        int u, v, c;
        scanf("%d%d%d", &u, &v, &c);
        w[u][v] = c;
    }
    long long d[205][2];
    int done[205][2] = {0};
    for (int i = 0; i < n; i++)
        d[i][0] = d[i][1] = INF;
    d[0][0] = 0;
    for (int step = 0; step < 2 * n; step++) {
        int u = -1, k = -1;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < 2; j++)
                if (!done[i][j] && (u < 0 || d[i][j] < d[u][k])) {
                    u = i;
                    k = j;
                }
        if (u < 0 || d[u][k] == INF)
            break;
        done[u][k] = 1;
        long long base = d[u][k];
        for (int v = 0; v < n; v++)
            if (w[u][v]) {
                long long nd = base + w[u][v];
                if (nd < d[v][0]) {
                    d[v][1] = d[v][0];
                    d[v][0] = nd;
                } else if (nd > d[v][0] && nd < d[v][1])
                    d[v][1] = nd;
            }
    }
    printf("%lld\n", d[n - 1][1] == INF ? -1 : d[n - 1][1]);
    return 0;
}

