}
int cmpint(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
long long a[26][26], res[26][26], tmp[26][26];
int n;
const long long INF = 4000000000000000LL;
void multiply(long long x[26][26], long long y[26][26]) {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            tmp[i][j] = INF;
            for (int k = 0; k < n; k++)
                if (x[i][k] < INF && y[k][j] < INF)
                    tmp[i][j] = minll(tmp[i][j], x[i][k] + y[k][j]);
        }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            x[i][j] = tmp[i][j];
}

int main(void) {
    int m;
    long long k;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            a[i][j] = INF;
            res[i][j] = i == j ? 0 : INF;
        }
    for (int i = 0; i < m; i++) {
        int u, v, c;
        scanf("%d%d%d", &u, &v, &c);
        a[u][v] = c;
    }
    scanf("%lld", &k);
    while (k) {
        if (k & 1)
            multiply(res, a);
        k >>= 1;
        if (k)
            multiply(a, a);
    }
    printf("%lld\n", res[0][n - 1] == INF ? -1 : res[0][n - 1]);
    return 0;
}

