    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
const long long INF = 1000000000000LL;
long long d[81][81], dp[1024][10];

int main(void) {
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            d[i][j] = i == j ? 0 : INF;
    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d%d%d", &u, &v, &w);
        d[u][v] = w;
    }
    for (int k = 0; k < n; k++)
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                d[i][j] = minll(d[i][j], d[i][k] + d[k][j]);
    int r, s[10];
    scanf("%d", &r);
    for (int i = 0; i < r; i++)
        scanf("%d", &s[i]);
    for (int mask = 0; mask < (1 << r); mask++)
        for (int j = 0; j < r; j++)
            dp[mask][j] = INF;
    for (int j = 0; j < r; j++)
        dp[1 << j][j] = d[0][s[j]];
    for (int mask = 1; mask < (1 << r); mask++)
        for (int j = 0; j < r; j++)
            if (mask & (1 << j))
                for (int k = 0; k < r; k++)
                    if (!(mask & (1 << k)))
                        dp[mask | (1 << k)][k] =
                            minll(dp[mask | (1 << k)][k], dp[mask][j] + d[s[j]][s[k]]);
    long long ans = r ? INF : d[0][n - 1];
    for (int j = 0; j < r; j++)
        ans = minll(ans, dp[(1 << r) - 1][j] + d[s[j]][n - 1]);
    printf("%lld\n", ans >= INF ? -1 : ans);
    return 0;
}

