#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

long long minll(long long a, long long b) {
    return a < b ? a : b;
}
long long maxll(long long a, long long b) {
    return a > b ? a : b;
}
int cmpint(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
int n, w[205][205];
const long long INF = 4000000000000000LL;
typedef struct {
    long long d;
    int u;
} Item;
Item heap[30005];
int hs;
void push(long long d, int u) {
    int i = ++hs;
    while (i > 1 && heap[i / 2].d > d) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i] = (Item){d, u};
}
Item pop(void) {
    Item ans = heap[1], last = heap[hs--];
    int i = 1;
    while (2 * i <= hs) {
        int c = 2 * i;
        if (c < hs && heap[c + 1].d < heap[c].d)
            c++;
        if (heap[c].d >= last.d)
            break;
        heap[i] = heap[c];
        i = c;
    }
    heap[i] = last;
    return ans;
}

int main(void) {
    int m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++) {
        int u, v, c;
        scanf("%d%d%d", &u, &v, &c);
        w[u][v] = c;
    }
    int k, count[205] = {0};
    scanf("%d", &k);
    push(0, 0);
    long long ans = -1;
    while (hs) {
        Item x = pop();
        int u = x.u;
        if (count[u] >= k)
            continue;
        count[u]++;
        if (u == n - 1 && count[u] == k) {
            ans = x.d;
            break;
        }
        for (int v = 0; v < n; v++)
            if (w[u][v])
                push(x.d + w[u][v], v);
    }
    printf("%lld\n", ans);
    return 0;
}

