int a, b, g[205][205], mate[205], seen[205], zl[205], zr[205];
int aug(int u) {
    for (int v = 0; v < b; v++)
        if (g[u][v] && !seen[v]) {
            seen[v] = 1;
            if (mate[v] < 0 || aug(mate[v])) {
                mate[v] = u;
