}
typedef struct {
    int v, next, cap, cost;
} E;
E e[20005];
int head[205], ec;
void edge(int u, int v, int cost) {
    e[ec] = (E){v, head[u], 1, cost};
    head[u] = ec++;
    e[ec] = (E){u, head[v], 0, -cost};
    head[v] = ec++;
}

int main(void) {
    int n, m;
    scanf("%d%d", &n, &m);
    int s = 2 * n, t = s + 1, V = t + 1;
    for (int i = 0; i < V; i++)
        head[i] = -1;
    for (int i = 0; i < m; i++) {
        int u, v, c;
        scanf("%d%d%d", &u, &v, &c);
        edge(u, n + v, c);
    }
    for (int i = 0; i < n; i++) {
        edge(s, i, 0);
        edge(n + i, t, 0);
    }
    long long answer = 0;
    int f = 0;
    while (f < n) {
        int d[205], prev[205];
        for (int i = 0; i < V; i++) {
            d[i] = 1000000000;
            prev[i] = -1;
        }
        d[s] = 0;
        for (int step = 0; step < V - 1; step++) {
            int changed = 0;
            for (int u = 0; u < V; u++)
                if (d[u] < 1000000000)
                    for (int k = head[u]; k != -1; k = e[k].next)
                        if (e[k].cap && d[e[k].v] > d[u] + e[k].cost) {
                            d[e[k].v] = d[u] + e[k].cost;
                            prev[e[k].v] = k;
                            changed = 1;
                        }
            if (!changed)
                break;
        }
        if (prev[t] < 0)
            break;
        answer += d[t];
        f++;
        for (int v = t; v != s; v = e[prev[v] ^ 1].v) {
            int k = prev[v];
            e[k].cap--;
            e[k ^ 1].cap++;
        }
    }
    printf("%lld\n", f == n ? answer : -1);
    return 0;
}

