int main(void) {
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        g[u][v]++;
        out[u]++;
        in[v]++;
    }
    int plus = 0, minus = 0, ok = 1;
    for (int u = 0; u < n; u++) {
        int d = out[u] - in[u];
        if (d == 1) {
            plus++;
            if (u != 0)
                ok = 0;
        } else if (d == -1)
            minus++;
        else if (d)
            ok = 0;
    }
    if (!((plus == 0 && minus == 0) || (plus == 1 && minus == 1)))
        ok = 0;
    int top = 0, len = 0;
    stack[top++] = 0;
    while (top) {
        int u = stack[top - 1];
        while (next[u] < n && !g[u][next[u]])
            next[u]++;
        if (next[u] < n) {
            int v = next[u];
            g[u][v]--;
            stack[top++] = v;
        } else {
            answer[len++] = u;
            top--;
        }
    }
    if (!ok || len != m + 1) {
        puts("IMPOSSIBLE");
        return 0;
    }
    for (int i = len - 1; i >= 0; i--)
        printf("%s%d", i == len - 1 ? "" : " ", answer[i]);
