long long minll(long long a, long long b) {
    return a < b ? a : b;
}
long long maxll(long long a, long long b) {
    return a > b ? a : b;
}
int cmpint(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
typedef struct {
    int u, v, w, id, used;
} Road;
Road edges[3005];
int parent[205];
int root(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}
int merge(int a, int b) {
    a = root(a);
    b = root(b);
    if (a == b)
        return 0;
    parent[a] = b;
    return 1;
}
int cmproad(const void *x, const void *y) {
    const Road *a = x, *b = y;
    if (a->w != b->w)
        return (a->w > b->w) - (a->w < b->w);
    return (a->id > b->id) - (a->id < b->id);
}
int N, tree[205][205], up[9][205], mx[9][205], depth[205];
void walk(int u, int p) {
    for (int v = 0; v < N; v++)
        if (tree[u][v] && v != p) {
            up[0][v] = u;
            mx[0][v] = tree[u][v];
            depth[v] = depth[u] + 1;
            walk(v, u);
        }
}
int pathmax(int u, int v) {
    int ans = 0;
    if (depth[u] < depth[v]) {
        int t = u;
        u = v;
        v = t;
    }
    for (int k = 8; k >= 0; k--)
        if (depth[u] - (1 << k) >= depth[v]) {
            ans = (int)maxll(ans, mx[k][u]);
            u = up[k][u];
        }
    if (u == v)
        return ans;
    for (int k = 8; k >= 0; k--)
        if (up[k][u] != up[k][v]) {
            ans = (int)maxll(ans, maxll(mx[k][u], mx[k][v]));
            u = up[k][u];
            v = up[k][v];
        }
    return (int)maxll(ans, maxll(mx[0][u], mx[0][v]));
}

int main(void) {
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < n; i++)
        parent[i] = i;
    for (int i = 0; i < m; i++) {
        scanf("%d%d%d", &edges[i].u, &edges[i].v, &edges[i].w);
        edges[i].id = i;
    }
    qsort(edges, m, sizeof *edges, cmproad);
    long long total = 0;
    int count = 0;
    for (int i = 0; i < m; i++)
        if (merge(edges[i].u, edges[i].v)) {
            edges[i].used = 1;
            tree[edges[i].u][edges[i].v] = tree[edges[i].v][edges[i].u] = edges[i].w;
            total += edges[i].w;
            count++;
        }
    if (count != n - 1) {
        puts("-1");
        return 0;
    }
    N = n;
    walk(0, -1);
    for (int k = 1; k < 9; k++)
        for (int u = 0; u < n; u++) {
            up[k][u] = up[k - 1][up[k - 1][u]];
            mx[k][u] = (int)maxll(mx[k - 1][u], mx[k - 1][up[k - 1][u]]);
        }
    long long answer = LLONG_MAX;
    for (int i = 0; i < m; i++)
        if (!edges[i].used)
            answer =
                minll(answer, total + edges[i].w - pathmax(edges[i].u, edges[i].v));
    printf("%lld\n", answer == LLONG_MAX ? -1 : answer);
    return 0;
}

