}
typedef struct {
    int u, v, w, id, used;
} Road;
Road edges[3005];
int parent[205];
int root(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}
int merge(int a, int b) {
    a = root(a);
    b = root(b);
    if (a == b)
        return 0;
    parent[a] = b;
    return 1;
}
int cmproad(const void *x, const void *y) {
    const Road *a = x, *b = y;
    if (a->w != b->w)
        return (a->w > b->w) - (a->w < b->w);
    return (a->id > b->id) - (a->id < b->id);
}
int h[205], to[6005], nx[6005], orig[6005], ne, tin[205], low[205], clock_,
    critical[3005];
void linkedge(int u, int v, int id) {
    to[ne] = v;
    orig[ne] = id;
    nx[ne] = h[u];
    h[u] = ne++;
}
void dfsbridge(int u, int pe) {
    tin[u] = low[u] = ++clock_;
    for (int e = h[u]; e != -1; e = nx[e]) {
        if ((e ^ 1) == pe)
            continue;
        int v = to[e];
        if (!tin[v]) {
            dfsbridge(v, e);
            if (low[v] < low[u])
                low[u] = low[v];
            if (low[v] > tin[u])
                critical[orig[e]] = 1;
        } else if (tin[v] < low[u])
            low[u] = tin[v];
    }
}

int main(void) {
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < n; i++)
        parent[i] = i;
    for (int i = 0; i < m; i++) {
        scanf("%d%d%d", &edges[i].u, &edges[i].v, &edges[i].w);
        edges[i].id = i;
    }
    qsort(edges, m, sizeof *edges, cmproad);
    for (int l = 0; l < m;) {
        int r = l;
        while (r < m && edges[r].w == edges[l].w)
            r++;
        for (int u = 0; u < n; u++) {
            h[u] = -1;
            tin[u] = low[u] = 0;
        }
        ne = clock_ = 0;
        for (int i = l; i < r; i++) {
            int u = root(edges[i].u), v = root(edges[i].v);
