                linkedge(u, v, edges[i].id);
                linkedge(v, u, edges[i].id);
            }
        }
        for (int u = 0; u < n; u++)
            if (h[u] != -1 && !tin[u])
                dfsbridge(u, -1);
        for (int i = l; i < r; i++)
            merge(edges[i].u, edges[i].v);
        l = r;
    }
    int first = 1;
    for (int i = 0; i < m; i++)
        if (critical[i]) {
            printf("%s%d", first ? "" : " ", i);
            first = 0;
        }
    if (first)
        puts("EMPTY");
    else
        puts("");
    return 0;
}

