int cmpint(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
int n;
long long b1[2005], b2[2005];
void add(long long *b, int x, long long v) {
    for (; x <= n; x += x & -x)
        b[x] += v;
}
long long query(long long *b, int x) {
    long long s = 0;
    for (; x; x -= x & -x)
        s += b[x];
    return s;
}
void rangeadd(int l, int r, long long v) {
    l++;
    r++;
    add(b1, l, v);
    add(b1, r + 1, -v);
    add(b2, l, v * (l - 1));
    add(b2, r + 1, -v * r);
}
long long prefix(int x) {
    return x * query(b1, x) - query(b2, x);
}

int main(void) {
    int q;
    scanf("%d%d", &n, &q);
    for (int i = 0; i < n; i++) {
        long long x;
        scanf("%lld", &x);
        rangeadd(i, i, x);
    }
    while (q--) {
        int op, l, r;
        scanf("%d%d%d", &op, &l, &r);
        if (op == 1) {
            long long x;
            scanf("%lld", &x);
            rangeadd(l, r, x);
        } else
            printf("%lld\n", prefix(r + 1) - prefix(l));
    }
    return 0;
}

