    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
int n;
long long mn[8005], setv[8005], plus[8005];
int has[8005];
void applySet(int p, long long x) {
    mn[p] = setv[p] = x;
    plus[p] = 0;
    has[p] = 1;
}
void applyAdd(int p, long long x) {
    mn[p] += x;
    if (has[p])
        setv[p] += x;
    else
        plus[p] += x;
}
void push(int p) {
    if (has[p]) {
        applySet(p * 2, setv[p]);
        applySet(p * 2 + 1, setv[p]);
        has[p] = 0;
    }
    if (plus[p]) {
        applyAdd(p * 2, plus[p]);
        applyAdd(p * 2 + 1, plus[p]);
        plus[p] = 0;
    }
}
void build(int p, int l, int r) {
    if (l == r) {
        scanf("%lld", &mn[p]);
        return;
    }
    int m = (l + r) / 2;
    build(p * 2, l, m);
    build(p * 2 + 1, m + 1, r);
    mn[p] = minll(mn[p * 2], mn[p * 2 + 1]);
}
void update(int p, int l, int r, int a, int b, long long x, int type) {
    if (a <= l && r <= b) {
        if (type == 1)
            applySet(p, x);
        else
            applyAdd(p, x);
        return;
    }
    push(p);
    int m = (l + r) / 2;
    if (a <= m)
        update(p * 2, l, m, a, b, x, type);
    if (b > m)
        update(p * 2 + 1, m + 1, r, a, b, x, type);
    mn[p] = minll(mn[p * 2], mn[p * 2 + 1]);
}
long long get(int p, int l, int r, int a, int b) {
    if (a <= l && r <= b)
        return mn[p];
    push(p);
    int m = (l + r) / 2;
    long long ans = LLONG_MAX;
    if (a <= m)
        ans = minll(ans, get(p * 2, l, m, a, b));
    if (b > m)
        ans = minll(ans, get(p * 2 + 1, m + 1, r, a, b));
    return ans;
}

