typedef struct {
    long long sum, pref, suf, best;
    int valid;
} Node;
Node tree[8005];
Node merge(Node a, Node b) {
    if (!a.valid)
        return b;
    if (!b.valid)
        return a;
    Node c = {a.sum + b.sum, maxll(a.pref, a.sum + b.pref), maxll(b.suf, b.sum + a.suf),
              maxll(maxll(a.best, b.best), a.suf + b.pref), 1};
    return c;
}
void set(int p, int l, int r, int x, long long value) {
    if (l == r) {
        tree[p] = (Node){value, value, value, value, 1};
        return;
    }
    int m = (l + r) / 2;
    if (x <= m)
        set(p * 2, l, m, x, value);
    else
        set(p * 2 + 1, m + 1, r, x, value);
    tree[p] = merge(tree[p * 2], tree[p * 2 + 1]);
}
Node get(int p, int l, int r, int a, int b) {
    if (b < l || r < a)
        return (Node){0, 0, 0, 0, 0};
    if (a <= l && r <= b)
        return tree[p];
    int m = (l + r) / 2;
    return merge(get(p * 2, l, m, a, b), get(p * 2 + 1, m + 1, r, a, b));
}

