int L[60005], R[60005], cnt[60005], roots[2005], nodes;
int insert(int old, int l, int r, int x) {
    int p = ++nodes;
    L[p] = L[old];
    R[p] = R[old];
    cnt[p] = cnt[old] + 1;
    if (l < r) {
        int m = (l + r) / 2;
        if (x <= m)
            L[p] = insert(L[old], l, m, x);
        else
            R[p] = insert(R[old], m + 1, r, x);
    }
    return p;
}
int kth(int a, int b, int l, int r, int k) {
    if (l == r)
        return l;
    int c = cnt[L[b]] - cnt[L[a]], m = (l + r) / 2;
    if (k <= c)
        return kth(L[a], L[b], l, m, k);
    return kth(R[a], R[b], m + 1, r, k - c);
}
int lower(int *a, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) / 2;
        if (a[m] < x)
            l = m + 1;
        else
            r = m;
    }
    return l;
}

