    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
typedef struct {
    int l, r, id;
} Query;
Query ask[2005];
int block;
int cmpQ(const void *x, const void *y) {
    const Query *a = x, *b = y;
    int p = a->l / block, q = b->l / block;
    if (p != q)
        return (p > q) - (p < q);
    return p % 2 ? (b->r > a->r) - (b->r < a->r) : (a->r > b->r) - (a->r < b->r);
}

int main(void) {
    int n, q, a[2005], freq[2005] = {0}, ans[2005];
