long long minll(long long a, long long b) {
    return a < b ? a : b;
}
long long maxll(long long a, long long b) {
    return a > b ? a : b;
}
int cmpint(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
typedef struct {
    int u, v, next;
} Event;
Event events[50005];
int head[8005], eventCount, parent[505], sz[505], historyA[50005], historyB[50005],
    historySize[50005], top, op[2005], uval[2005], vval[2005];
int root(int x) {
    while (parent[x] != x)
        x = parent[x];
    return x;
}
void merge(int a, int b) {
    a = root(a);
    b = root(b);
    if (a == b)
        return;
    if (sz[a] < sz[b]) {
        int t = a;
        a = b;
        b = t;
    }
    historyA[top] = a;
    historyB[top] = b;
    historySize[top++] = sz[a];
    parent[b] = a;
    sz[a] += sz[b];
}
void insert(int p, int l, int r, int a, int b, int u, int v) {
    if (a > r || b < l)
        return;
    if (a <= l && r <= b) {
        events[++eventCount] = (Event){u, v, head[p]};
        head[p] = eventCount;
        return;
    }
    int m = (l + r) / 2;
    insert(p * 2, l, m, a, b, u, v);
    insert(p * 2 + 1, m + 1, r, a, b, u, v);
}
void traverse(int p, int l, int r) {
    int checkpoint = top;
    for (int e = head[p]; e; e = events[e].next)
        merge(events[e].u, events[e].v);
    if (l == r) {
        if (op[l] == 3)
            puts(root(uval[l]) == root(vval[l]) ? "YES" : "NO");
    } else {
        int m = (l + r) / 2;
        traverse(p * 2, l, m);
        traverse(p * 2 + 1, m + 1, r);
    }
    while (top > checkpoint) {
        top--;
        int a = historyA[top], b = historyB[top];
        parent[b] = b;
        sz[a] = historySize[top];
    }
}

int main(void) {
    int n, q;
    static int start[505][505];
    scanf("%d%d", &n, &q);
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        sz[i] = 1;
        for (int j = 0; j < n; j++)
            start[i][j] = -1;
    }
    for (int t = 0; t < q; t++) {
        scanf("%d%d%d", &op[t], &uval[t], &vval[t]);
        int u = uval[t], v = vval[t];
        if (u > v) {
            int x = u;
            u = v;
            v = x;
        }
        if (op[t] == 1)
            start[u][v] = t;
        else if (op[t] == 2) {
            insert(1, 0, q - 1, start[u][v], t - 1, u, v);
            start[u][v] = -1;
        }
    }
    for (int u = 0; u < n; u++)
        for (int v = u + 1; v < n; v++)
            if (start[u][v] >= 0)
                insert(1, 0, q - 1, start[u][v], q - 1, u, v);
    traverse(1, 0, q - 1);
    return 0;
}

