Road roads[6005];
Ask asks[2005];
int parent[2005], size[2005];
int root(int x) {
    if (parent[x] != x)
        parent[x] = root(parent[x]);
    return parent[x];
}
int cmpR(const void *a, const void *b) {
    const Road *x = a, *y = b;
