}
int parent[2005], size[2005];
long long delta[2005];
int root(int x) {
    if (parent[x] == x)
        return x;
    int p = parent[x];
    parent[x] = root(p);
    delta[x] += delta[p];
    return parent[x];
}

int main(void) {
    int n, q;
    scanf("%d%d", &n, &q);
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    int answer = 0;
    for (int i = 1; i <= q; i++) {
        int u, v;
        long long w;
        scanf("%d%d%lld", &u, &v, &w);
        if (answer)
            continue;
        int a = root(u), b = root(v);
        long long du = delta[u], dv = delta[v];
        if (a == b) {
            if (dv - du != w)
                answer = i;
        } else {
            long long shift = w + du - dv;
            if (size[a] < size[b]) {
                parent[a] = b;
                delta[a] = -shift;
                size[b] += size[a];
            } else {
                parent[b] = a;
                delta[b] = shift;
                size[a] += size[b];
            }
        }
