int build(int l, int r) {
    int p = ++used;
    if (r - l == 1) {
        nodes[p].sum = initial[l];
        return p;
    }
    int m = (l + r) / 2;
    nodes[p].l = build(l, m);
    nodes[p].r = build(m, r);
    nodes[p].sum = nodes[nodes[p].l].sum + nodes[nodes[p].r].sum;
    return p;
}
int assign(int old, int l, int r, int x, int value) {
    int p = ++used;
    nodes[p] = nodes[old];
    if (r - l == 1) {
        nodes[p].sum = value;
        return p;
    }
    int m = (l + r) / 2;
    if (x < m)
        nodes[p].l = assign(nodes[old].l, l, m, x, value);
    else
        nodes[p].r = assign(nodes[old].r, m, r, x, value);
    nodes[p].sum = nodes[nodes[p].l].sum + nodes[nodes[p].r].sum;
    return p;
}
