long long a[10005], s[40020], sq[40020], lazy[40020];
void apply(int p, int len, long long d) {
    sq[p] += 2 * d * s[p] + len * d * d;
    s[p] += len * d;
    lazy[p] += d;
}
void pull(int p) {
    s[p] = s[p * 2] + s[p * 2 + 1];
    sq[p] = sq[p * 2] + sq[p * 2 + 1];
}
void build(int p, int l, int r) {
    if (r - l == 1) {
        s[p] = a[l];
        sq[p] = a[l] * a[l];
        return;
    }
    int m = (l + r) / 2;
    build(p * 2, l, m);
    build(p * 2 + 1, m, r);
    pull(p);
}
void push(int p, int l, int r) {
    if (!lazy[p] || r - l == 1)
        return;
    int m = (l + r) / 2;
    apply(p * 2, m - l, lazy[p]);
    apply(p * 2 + 1, r - m, lazy[p]);
    lazy[p] = 0;
}
void update(int p, int l, int r, int a0, int b, long long d) {
    if (a0 <= l && r <= b) {
        apply(p, r - l, d);
        return;
    }
    push(p, l, r);
    int m = (l + r) / 2;
    if (a0 < m)
        update(p * 2, l, m, a0, b, d);
    if (b > m)
        update(p * 2 + 1, m, r, a0, b, d);
    pull(p);
}
long long query(int p, int l, int r, int a0, int b) {
    if (a0 <= l && r <= b)
        return sq[p];
    push(p, l, r);
    int m = (l + r) / 2;
    long long ans = 0;
    if (a0 < m)
        ans += query(p * 2, l, m, a0, b);
    if (b > m)
        ans += query(p * 2 + 1, m, r, a0, b);
    return ans;
}

int main(void) {
    int n, q;
    scanf("%d%d", &n, &q);
    for (int i = 0; i < n; i++)
        scanf("%lld", &a[i]);
    build(1, 0, n);
    while (q--) {
        int op, l, r;
        scanf("%d%d%d", &op, &l, &r);
        if (op == 1) {
            long long d;
