void addbit(int p, long long x, int n) {
    for (; p <= n; p += p & -p)
        bit[p] += x;
}
long long prefix(int p) {
    long long s = 0;
    for (; p; p -= p & -p)
        s += bit[p];
    return s;
}
void rangeadd(int l, int r, long long x, int n) {
    addbit(l + 1, x, n);
    addbit(r + 2, -x, n);
}

int main(void) {
    int n, g, q;
    scanf("%d%d%d", &n, &g, &q);
    for (int i = 0; i < g; i++) {
        head[i] = -1;
        lo[i] = 1;
        hi[i] = q + 1;
    }
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        nextpos[i] = head[x];
        head[x] = i;
    }
    for (int i = 0; i < g; i++)
        scanf("%lld", &target[i]);
