        for (int i = 0; i <= q; i++)
            bucket[i] = -1;
        for (int i = 0; i < g; i++)
            if (lo[i] < hi[i]) {
                any = 1;
                int mid = (lo[i] + hi[i]) / 2;
                nextgroup[i] = bucket[mid];
                bucket[mid] = i;
            }
        if (!any)
            break;
        memset(bit, 0, sizeof bit);
        for (int day = 1; day <= q; day++) {
            if (el[day] <= er[day])
                rangeadd(el[day], er[day], ev[day], n);
            else {
                rangeadd(el[day], n - 1, ev[day], n);
                rangeadd(0, er[day], ev[day], n);
            }
            for (int group = bucket[day]; group != -1; group = nextgroup[group]) {
                long long sum = 0;
                for (int p = head[group]; p != -1; p = nextpos[p]) {
                    sum += prefix(p + 1);
                    if (sum >= target[group])
                        break;
                }
                if (sum >= target[group])
                    hi[group] = day;
                else
                    lo[group] = day + 1;
            }
        }
    }
    for (int i = 0; i < g; i++)
        printf("%s%d", i ? " " : "", lo[i] == q + 1 ? -1 : lo[i]);
