            unite(x, x - 1);
        if (x + 1 < n && active[x + 1])
            unite(x, x + 1);
        if (sum[find(x)] > best)
            best = sum[find(x)];
    }
    for (int i = 0; i < n; i++)
        printf("%s%lld", i ? " " : "", answer[i]);
    puts("");
    return 0;
}

